/**
 * Resolves query text, guild code, or BT code to a matching Business Type.
 * Supports exact BT code lookup, Iranian guild code lookup, keyword matching,
 * and frontier/hybrid fallbacks (BT-0742 through BT-0753).
 */
export function resolveBusinessType(query) {
  if (!query) {
    return BUSINESS_TYPES_MAP["BT-0753"] || BUSINESS_TYPES[0];
  }

  const q = String(query).trim().toLowerCase();

  // 1. Direct BT-ID match (e.g. BT-0123)
  const btMatch = q.match(/bt-\d{4}/i);
  if (btMatch) {
    const matchedId = btMatch[0].toUpperCase();
    if (BUSINESS_TYPES_MAP[matchedId]) {
      return BUSINESS_TYPES_MAP[matchedId];
    }
  }

  // 2. Direct Iranian Guild Code match (5-8 digits)
  const codeMatch = q.match(/\b\d{5,8}\b/);
  if (codeMatch) {
    const foundByGuild = BUSINESS_TYPES.find(b => b.iranianGuildCode === codeMatch[0]);
    if (foundByGuild) return foundByGuild;
  }

  // 3. Exact title match
  const foundByTitle = BUSINESS_TYPES.find(b => 
    b.titleFa.toLowerCase() === q || b.titleEn.toLowerCase() === q
  );
  if (foundByTitle) return foundByTitle;

  // 4. Frontier Business Types (BT-0742 to BT-0752)
  if (q.includes("آشپزخانه ابری") || q.includes("دارک کیچن") || q.includes("ghost kitchen")) return BUSINESS_TYPES_MAP["BT-0742"];
  if (q.includes("میکرو سس") || q.includes("micro-saas")) return BUSINESS_TYPES_MAP["BT-0743"];
  if (q.includes("کیوکامرس") || q.includes("q-commerce") || q.includes("تحویل فوری")) return BUSINESS_TYPES_MAP["BT-0744"];
  if (q.includes("هوش مصنوعی") || q.includes("ai") || q.includes("agentic") || q.includes("عامل هوشمند") || q.includes("مدل زبانی") || q.includes("llm")) return BUSINESS_TYPES_MAP["BT-0745"];
  if (q.includes("چاپ سه بعدی") || q.includes("3d print") || q.includes("فابریکیتور")) return BUSINESS_TYPES_MAP["BT-0746"];
  if (q.includes("کوورکینگ") || q.includes("co-working") || q.includes("فضای اشتراکی")) return BUSINESS_TYPES_MAP["BT-0747"];
  if (q.includes("تله هلث") || q.includes("سلامت از راه دور") || q.includes("telehealth")) return BUSINESS_TYPES_MAP["BT-0748"];
  if (q.includes("کریتور کامرس") || q.includes("creator commerce")) return BUSINESS_TYPES_MAP["BT-0749"];
  if (q.includes("اقتصاد چرخشی") || q.includes("circular economy") || q.includes("بازیافت هوشمند")) return BUSINESS_TYPES_MAP["BT-0750"];
  if (q.includes("میکرو هلدینگ") || q.includes("هلدینگ خرد") || q.includes("استودیو سرمایه گذاری")) return BUSINESS_TYPES_MAP["BT-0751"];
  if (q.includes("بوت کمپ") || q.includes("isa bootcamp") || q.includes("تسهیم درآمد")) return BUSINESS_TYPES_MAP["BT-0752"];

  // 5. Keyword score match with word-boundary and stopword awareness
  const stopWords = new Set(["کار", "کسب", "بدون", "انواع", "کلیه", "ارائه", "خدمات", "فروش", "تولید", "برای", "جهت", "مرکز"]);
  const qTokens = q.split(/[\s,،\-–_./\\]+/).filter(t => t.length > 2 && !stopWords.has(t));
  let bestMatch = null;
  let maxScore = 0;

  for (const bt of BUSINESS_TYPES) {
    let score = 0;
    const titleFaLower = bt.titleFa.toLowerCase();
    const titleEnLower = bt.titleEn.toLowerCase();

    if (q.includes(titleFaLower)) score += 25;
    if (q.includes(titleEnLower)) score += 20;

    for (const token of qTokens) {
      if (titleFaLower.includes(token)) {
        score += 3;
      }
    }

    for (const kw of bt.keywords) {
      const kwLower = kw.toLowerCase();
      if (q.includes(kwLower)) {
        if (kwLower.includes(" ") || qTokens.includes(kwLower)) {
          score += 10;
        } else {
          score += 5;
        }
      }
    }

    if (score > maxScore) {
      maxScore = score;
      bestMatch = bt;
    }
  }

  if (bestMatch && maxScore >= 10) {
    return bestMatch;
  }

  // Universal Default Fallback: BT-0753 (مدل ترکیبی سفارشی پیشگام / کسب‌وکار چندرشته‌ای تعریف‌نشده)
  return BUSINESS_TYPES_MAP["BT-0753"] || BUSINESS_TYPES[0];
}
